/* Not Human case studies: the single source for the case documents (pearl), the demos (night) and the index.
   Edit a case here and every page that shows it changes.

   HONESTY RULE (std-evidence-labels, hb-services): these are ILLUSTRATIVE cases. Each "client" is a composite agency
   built from the kinds of work the audit playbooks describe; no client, quote or result here is real. Numbers are
   modelled with the field note "Hours first, money second" method (hours told x share an agent can really take x a
   stated rate), with revenue upside kept apart from cost. Prices and rates are assumptions, written as such.
   Tool names are the client's software, shown as examples; we do not imply any partnership. */
var NHC = window.NHC = window.NHC || {};

/* ------------------------------------------------------------------ how every system runs (shared by all cases) */
NHC.stack = {
  title: 'How the system runs',
  lede: 'Every system we build runs the same way, whatever the department. Here is what sits where, in plain words.',
  layers: [
    { icon: 'cloud', name: 'A small private server, in your own cloud account',
      plain: 'The agents live on one always-on server that you own (on AWS, Google Cloud or Hetzner, chosen at the audit). It keeps working with every laptop closed, at night and on weekends.',
      tech: 'One Linux VM sized to the workload, provisioned from a script, patched automatically, backed up nightly.' },
    { icon: 'mesh', name: 'A private network nobody else can reach',
      plain: 'The server has no public door. Only your team’s own devices, joined to your private network, can open it. We use Tailscale for this: each person signs in with their work account, and you decide who reaches what.',
      tech: 'Tailscale tailnet over WireGuard encryption, access rules per person and per device, no open inbound ports. Tool events arrive through one narrow, signed webhook endpoint.' },
    { icon: 'key', name: 'Agents get their own accounts, never yours',
      plain: 'Each agent has its own login in each tool, with only the permissions its job needs. Most start read-only. An agent that drafts invoices can create drafts but cannot approve or send them.',
      tech: 'Service accounts and scoped API keys per agent, stored in an encrypted secrets store, rotated, never in code or chat. Revoking one key stops one agent.' },
    { icon: 'brain', name: 'A second brain the agents read',
      plain: 'Your processes, rules, client notes and every meeting summary are written into one knowledge base. The agents read it before they act, and your team can search it too. When a rule changes, you change it there once.',
      tech: 'Markdown files in a private Git repository, so every change is versioned and reversible, plus a search index. Meeting recordings are transcribed and summarised into it.' },
    { icon: 'person', name: 'A person on every decision that matters',
      plain: 'Agents prepare, people decide. Anything involving money, a promise to a client or something you cannot undo waits in an approval queue (in Slack or email) with the agent’s reasoning attached.',
      tech: 'Confidence thresholds per workflow: high confidence goes ahead, medium goes to the draft queue, low escalates. Approve, edit or reject in one click.' },
    { icon: 'sop', name: 'A log of everything, and an off switch',
      plain: 'Every action is written down: what the agent read, what it decided, why, and who approved it. One switch pauses every agent at once.',
      tech: 'Append-only audit log per run (sources, rules applied, confidence, approver), weekly usage and cost report, a global pause.' },
  ],
  models: 'Model-agnostic: each step uses the cheapest model that passes our tests (a strong model such as Claude for writing and judgement, small fast models for sorting). Business API terms, where providers do not train on your data.',
  owns: [
    ['You own the agents', 'The workflows, the rules and the code are yours, in your accounts.'],
    ['Your data stays home', 'Processing runs on your server. Nothing is copied into a platform of ours.'],
    ['Walk away anytime', 'If we stop working together, everything keeps running and stays yours.'],
    ['Built like a building', 'We design and build it; you get the keys and the blueprints.'],
  ],
};

NHC.glossary = [
  ['Agent', 'A program that reads, decides and acts on one job, inside your tools, following written rules.'],
  ['Second brain', 'Your company’s knowledge written down in one searchable place the agents read: processes, rules, clients, meetings.'],
  ['Approval queue', 'The list of things an agent prepared that wait for a person to approve, edit or reject.'],
  ['Confidence threshold', 'How sure an agent must be before it may go ahead without asking. Below it, a person decides.'],
  ['Shadow mode', 'The agent runs next to the team and shows what it would have done, without acting, until it proves itself.'],
  ['Tailscale', 'A private network for your devices and the agents’ server, so nothing is exposed to the open internet.'],
  ['API', 'The official door a tool offers for other software to read or write data, with its own keys.'],
  ['Webhook', 'A tool tapping the agents on the shoulder when something happens, such as a new email or a paid invoice.'],
];

NHC.note = 'Illustrative case. The agency is a composite built from typical audit findings; it is not a client. Every number is modelled from stated assumptions, and the math is shown.';

